 for(const r of rules){if(r.b&&(barren(lord)!==r.b[0]||barren(star)!==r.b[1]))continue;if(r.pair&&(lord.id!==r.pair[0]||star.id!==r.pair[1]))continue;if(r.ketu&&lord.id!=='Ke'&&star.id!=='Ke')continue;if(r.star&&star.id!==r.star)continue;if(r.groups&&!r.groups.some(g=>g.every(h=>houses.includes(h))))continue;matched.push(r.id);add(r.id,r.en,r.mr);}
 if(!matched.length)add('no-match','No unambiguous condition in the supplied childbirth table fully matches this selection.','दिलेल्या संतती तक्त्यातील स्पष्ट अट या निवडीशी पूर्ण जुळत नाही.');
